with open(r'C:\Users\nipon\Documents\opencode\idiom-master\scratch\ox_mnemonics\batch_033.json', 'r', encoding='utf-8') as f:
    batch_words = json.load(f)

expected_lemmas = [x['lemma'] for x in batch_words]

# Verification
missing = set(expected_lemmas) - set(mnemonics.keys())
extra = set(mnemonics.keys()) - set(expected_lemmas)

print('Missing:', missing)
print('Extra:', extra)
assert len(missing) == 0
assert len(extra) == 0

out_path = r'C:\Users\nipon\Documents\opencode\idiom-master\scratch\ox_mnemonics_done\batch_033_done.json'
with open(out_path, 'w', encoding='utf-8') as f:
    json.dump(mnemonics, f, ensure_ascii=False, indent=2)

print('Successfully written', len(mnemonics), 'mnemonics to', out_path)
